static struct PyGetSetDef __pyx_getsets_6pandas_5_libs_6tslibs_6period__Period[] = {
  {"ordinal", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_ordinal, 0, PyDoc_STR("\n        Return the integer ordinal for this Period.\n\n        The ordinal is the internal integer representation of the Period,\n        representing its position in the sequence of periods of the given\n        frequency. It counts from an epoch (e.g., for daily frequency,\n        ordinal 0 corresponds to January 1, 1970).\n\n        See Also\n        --------\n        Period.freq : Return the frequency of the Period.\n        Period.start_time : Return the start time of the Period.\n\n        Examples\n        --------\n        >>> period = pd.Period(\0472020-01\047, freq=\047M\047)\n        >>> period.ordinal\n        600\n\n        >>> period = pd.Period(\0472020-01-01\047, freq=\047D\047)\n        >>> period.ordinal\n        18262\n        "), 0},
  {"freq", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_freq, 0, PyDoc_STR("\n        Return the frequency object for this Period.\n\n        The frequency object represents the span of time that this Period covers.\n        It is a DateOffset that defines the interval type (e.g., daily, monthly).\n\n        See Also\n        --------\n        Period.freqstr : Return a string representation of the frequency.\n        Period.asfreq : Convert Period to desired frequency.\n\n        Examples\n        --------\n        >>> period = pd.Period(\0472020-01\047, freq=\047M\047)\n        >>> period.freq\n        <MonthEnd>\n        "), 0},
  {"dayofweek", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_dayofweek, 0, PyDoc_STR("\n        Return day of the week.\n\n        .. deprecated:: 3.1.0\n            Use :attr:`Period.day_of_week` instead.\n        "), 0},
  {"dayofyear", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_dayofyear, 0, PyDoc_STR("\n        Return day of the year.\n\n        .. deprecated:: 3.1.0\n            Use :attr:`Period.day_of_year` instead.\n        "), 0},
  {"year", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_year, 0, PyDoc_STR("\n        Return the year this Period falls on.\n\n        The year is derived from the internal representation of the Period\n        based on its ordinal value and frequency.\n\n        Returns\n        -------\n        int\n\n        See Also\n        --------\n        period.month : Get the month of the year for the given Period.\n        period.day : Return the day of the month the Period falls on.\n\n        Notes\n        -----\n        The year is based on the `ordinal` and `base` attributes of the Period.\n\n        Examples\n        --------\n        Create a Period object for January 2023 and get the year:\n\n        >>> period = pd.Period(\0472023-01\047, \047M\047)\n        >>> period.year\n        2023\n\n        Create a Period object for 01 January 2023 and get the year:\n\n        >>> period = pd.Period(\0472023\047, \047D\047)\n        >>> period.year\n        2023\n\n        Get the year for a period representing a quarter:\n\n        >>> period = pd.Period(\0472023Q2\047, \047Q\047)\n        >>> period.year\n        2023\n\n        Handle a case where the Period object is empty, which results in `NaN`:\n\n        >>> period = pd.Period(\047nan\047, \047M\047)\n        >>> period.year\n        nan\n        "), 0},
  {"month", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_month, 0, PyDoc_STR("\n        Return the month this Period falls on.\n\n        Months are numbered from 1 (January) through 12 (December).\n\n        Returns\n        -------\n        int\n\n        See Also\n        --------\n        period.week : Get the week of the year on the given Period.\n        Period.year : Return the year this Period falls on.\n        Period.day : Return the day of the month this Period falls on.\n\n        Notes\n        -----\n        The month is based on the `ordinal` and `base` attributes of the Period.\n\n        Examples\n        --------\n        Create a Period object for January 2022 and get the month:\n\n        >>> period = pd.Period(\0472022-01\047, \047M\047)\n        >>> period.month\n        1\n\n        Period object with no specified frequency, resulting in a default frequency:\n\n        >>> period = pd.Period(\0472022\047, \047Y\047)\n        >>> period.month\n        12\n\n        Create a Period object with a specified frequency but an incomplete date string:\n\n        >>> period = pd.Period(\0472022\047, \047M\047)\n        >>> period.month\n        1\n\n        Handle a case where the Period object is empty, which results in `NaN`:\n\n        >>> period = pd.Period(\047nan\047, \047M\047)\n        >>> period.month\n        nan\n        "), 0},
  {"day", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_day, 0, PyDoc_STR("\n        Get day of the month that a Period falls on.\n\n        The `day` property provides a simple way to access the day component\n        of a `Period` object, which represents time spans in various frequencies\n        (e.g., daily, hourly, monthly). If the period\047s frequency does not include\n        a day component (e.g., yearly or quarterly periods), the returned day\n        corresponds to the first day of that period.\n\n        Returns\n        -------\n        int\n\n        See Also\n        --------\n        Period.dayofweek : Get the day of the week.\n        Period.dayofyear : Get the day of the year.\n\n        Examples\n        --------\n        >>> p = pd.Period(\"2018-03-11\", freq=\047h\047)\n        >>> p.day\n        11\n        "), 0},
  {"hour", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_hour, 0, PyDoc_STR("\n        Get the hour of the day component of the Period.\n\n        For periods with a frequency shorter than a day, this returns the\n        hour portion of the time. For longer frequencies, it returns 0.\n\n        Returns\n        -------\n        int\n            The hour as an integer, between 0 and 23.\n\n        See Also\n        --------\n        Period.second : Get the second component of the Period.\n        Period.minute : Get the minute component of the Period.\n\n        Examples\n        --------\n        >>> p = pd.Period(\"2018-03-11 13:03:12.050000\")\n        >>> p.hour\n        13\n\n        Period longer than a day\n\n        >>> p = pd.Period(\"2018-03-11\", freq=\"M\")\n        >>> p.hour\n        0\n        "), 0},
  {"minute", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_minute, 0, PyDoc_STR("\n        Get minute of the hour component of the Period.\n\n        For periods with a frequency shorter than an hour, this returns the\n        minute portion of the time. For longer frequencies, it returns 0.\n\n        Returns\n        -------\n        int\n            The minute as an integer, between 0 and 59.\n\n        See Also\n        --------\n        Period.hour : Get the hour component of the Period.\n        Period.second : Get the second component of the Period.\n\n        Examples\n        --------\n        >>> p = pd.Period(\"2018-03-11 13:03:12.050000\")\n        >>> p.minute\n        3\n        "), 0},
  {"second", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_second, 0, PyDoc_STR("\n        Get the second component of the Period.\n\n        For periods with a frequency shorter than a minute, this returns the\n        second portion of the time. For longer frequencies, it returns 0.\n\n        Returns\n        -------\n        int\n            The second of the Period (ranges from 0 to 59).\n\n        See Also\n        --------\n        Period.hour : Get the hour component of the Period.\n        Period.minute : Get the minute component of the Period.\n\n        Examples\n        --------\n        >>> p = pd.Period(\"2018-03-11 13:03:12.050000\")\n        >>> p.second\n        12\n        "), 0},
  {"weekofyear", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_weekofyear, 0, PyDoc_STR("\n        Get the week of the year on the given Period.\n\n        Weeks are numbered according to ISO 8601, where the first week of\n        the year contains the first Thursday of the year.\n\n        Returns\n        -------\n        int\n\n        See Also\n        --------\n        Period.dayofweek : Get the day component of the Period.\n        Period.weekday : Get the day component of the Period.\n\n        Examples\n        --------\n        >>> p = pd.Period(\"2018-03-11\", \"h\")\n        >>> p.weekofyear\n        10\n\n        >>> p = pd.Period(\"2018-02-01\", \"D\")\n        >>> p.weekofyear\n        5\n\n        >>> p = pd.Period(\"2018-01-06\", \"D\")\n        >>> p.weekofyear\n        1\n        "), 0},
  {"week", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_week, 0, PyDoc_STR("\n        Get the week of the year on the given Period.\n\n        Weeks are numbered according to ISO 8601, where the first week of\n        the year contains the first Thursday of the year.\n\n        Returns\n        -------\n        int\n\n        See Also\n        --------\n        Period.dayofweek : Get the day component of the Period.\n        Period.weekday : Get the day component of the Period.\n\n        Examples\n        --------\n        >>> p = pd.Period(\"2018-03-11\", \"h\")\n        >>> p.week\n        10\n\n        >>> p = pd.Period(\"2018-02-01\", \"D\")\n        >>> p.week\n        5\n\n        >>> p = pd.Period(\"2018-01-06\", \"D\")\n        >>> p.week\n        1\n        "), 0},
  {"day_of_week", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_day_of_week, 0, PyDoc_STR("\n        Day of the week the period lies in, with Monday=0 and Sunday=6.\n\n        If the period frequency is lower than daily (e.g. hourly), and the\n        period spans over multiple days, the day at the start of the period is\n        used.\n\n        If the frequency is higher than daily (e.g. monthly), the last day\n        of the period is used.\n\n        Returns\n        -------\n        int\n            Day of the week.\n\n        See Also\n        --------\n        Period.day_of_week : Day of the week the period lies in.\n        Period.weekday : Alias of Period.day_of_week.\n        Period.day : Day of the month.\n        Period.dayofyear : Day of the year.\n\n        Examples\n        --------\n        >>> per = pd.Period(\0472017-12-31 22:00\047, \047h\047)\n        >>> per.day_of_week\n        6\n\n        For periods that span over multiple days, the day at the beginning of\n        the period is returned.\n\n        >>> per = pd.Period(\0472017-12-31 22:00\047, \0474h\047)\n        >>> per.day_of_week\n        6\n        >>> per.start_time.day_of_week\n        6\n\n        For periods with a frequency higher than days, the last day of the\n        period is returned.\n\n        >>> per = pd.Period(\0472018-01\047, \047M\047)\n        >>> per.day_of_week\n        2\n        >>> per.end_time.day_of_week\n        2\n        "), 0},
  {"weekday", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_weekday, 0, PyDoc_STR("\n        Day of the week the period lies in, with Monday=0 and Sunday=6.\n\n        If the period frequency is lower than daily (e.g. hourly), and the\n        period spans over multiple days, the day at the start of the period is\n        used.\n\n        If the frequency is higher than daily (e.g. monthly), the last day\n        of the period is used.\n\n        Returns\n        -------\n        int\n            Day of the week.\n\n        See Also\n        --------\n        Period.dayofweek : Day of the week the period lies in.\n        Period.weekday : Alias of Period.day_of_week.\n        Period.day : Day of the month.\n        Period.day_of_year : Day of the year.\n\n        Examples\n        --------\n        >>> per = pd.Period(\0472017-12-31 22:00\047, \047h\047)\n        >>> per.day_of_week\n        6\n\n        For periods that span over multiple days, the day at the beginning of\n        the period is returned.\n\n        >>> per = pd.Period(\0472017-12-31 22:00\047, \0474h\047)\n        >>> per.day_of_week\n        6\n        >>> per.start_time.day_of_week\n        6\n\n        For periods with a frequency higher than days, the last day of the\n        period is returned.\n\n        >>> per = pd.Period(\0472018-01\047, \047M\047)\n        >>> per.day_of_week\n        2\n        >>> per.end_time.day_of_week\n        2\n        "), 0},
  {"day_of_year", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_day_of_year, 0, PyDoc_STR("\n        Return the day of the year.\n\n        This attribute returns the day of the year on which the particular\n        date occurs. The return value ranges between 1 to 365 for regular\n        years and 1 to 366 for leap years.\n\n        Returns\n        -------\n        int\n            The day of year.\n\n        See Also\n        --------\n        Period.day : Return the day of the month.\n        Period.day_of_week : Return the day of week.\n        PeriodIndex.day_of_year : Return the day of year of all indexes.\n\n        Examples\n        --------\n        >>> period = pd.Period(\"2015-10-23\", freq=\047h\047)\n        >>> period.day_of_year\n        296\n        >>> period = pd.Period(\"2012-12-31\", freq=\047D\047)\n        >>> period.day_of_year\n        366\n        >>> period = pd.Period(\"2013-01-01\", freq=\047D\047)\n        >>> period.day_of_year\n        1\n        "), 0},
  {"quarter", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_quarter, 0, PyDoc_STR("\n        Return the quarter this Period falls on.\n\n        Quarter 1 includes January through March, quarter 2 includes April\n        through June, quarter 3 includes July through September, and quarter\n        4 includes October through December.\n\n        See Also\n        --------\n        Timestamp.quarter : Return the quarter of the Timestamp.\n        Period.year : Return the year of the period.\n        Period.month : Return the month of the period.\n\n        Examples\n        --------\n        >>> period = pd.Period(\0472022-04\047, \047M\047)\n        >>> period.quarter\n        2\n        "), 0},
  {"qyear", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_qyear, 0, PyDoc_STR("\n        Fiscal year the Period lies in according to its starting-quarter.\n\n        The `year` and the `qyear` of the period will be the same if the fiscal\n        and calendar years are the same. When they are not, the fiscal year\n        can be different from the calendar year of the period.\n\n        Returns\n        -------\n        int\n            The fiscal year of the period.\n\n        See Also\n        --------\n        Period.year : Return the calendar year of the period.\n\n        Examples\n        --------\n        If the natural and fiscal year are the same, `qyear` and `year` will\n        be the same.\n\n        >>> per = pd.Period(\0472018Q1\047, freq=\047Q\047)\n        >>> per.qyear\n        2018\n        >>> per.year\n        2018\n\n        If the fiscal year starts in April (`Q-MAR`), the first quarter of\n        2018 will start in April 2017. `year` will then be 2017, but `qyear`\n        will be the fiscal year, 2018.\n\n        >>> per = pd.Period(\0472018Q1\047, freq=\047Q-MAR\047)\n        >>> per.start_time\n        Timestamp(\0472017-04-01 00:00:00\047)\n        >>> per.qyear\n        2018\n        >>> per.year\n        2017\n        "), 0},
  {"days_in_month", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_days_in_month, 0, PyDoc_STR("\n        Get the total number of days in the month that this period falls on.\n\n        This value depends on the month and whether the year is a leap year\n        (e.g., February has 28 or 29 days).\n\n        Returns\n        -------\n        int\n\n        See Also\n        --------\n        Period.daysinmonth : Gets the number of days in the month.\n        DatetimeIndex.daysinmonth : Gets the number of days in the month.\n        calendar.monthrange : Returns a tuple containing weekday\n            (0-6 ~ Mon-Sun) and number of days (28-31).\n\n        Examples\n        --------\n        >>> p = pd.Period(\0472018-2-17\047)\n        >>> p.days_in_month\n        28\n\n        >>> pd.Period(\0472018-03-01\047).days_in_month\n        31\n\n        Handles the leap year case as well:\n\n        >>> p = pd.Period(\0472016-2-17\047)\n        >>> p.days_in_month\n        29\n        "), 0},
  {"daysinmonth", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_daysinmonth, 0, PyDoc_STR("\n        Get the total number of days of the month that this period falls on.\n\n        .. deprecated:: 3.1.0\n            Use :attr:`Period.days_in_month` instead.\n\n        Returns\n        -------\n        int\n\n        See Also\n        --------\n        Period.days_in_month : Return the days of the month.\n        Period.day_of_year : Return the day of the year.\n\n        Examples\n        --------\n        >>> p = pd.Period(\"2018-03-11\", freq=\047h\047)\n        >>> p.days_in_month\n        31\n        "), 0},
  {"is_leap_year", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_is_leap_year, 0, PyDoc_STR("\n        Return True if the period\047s year is in a leap year.\n\n        A leap year is a year with 366 days (instead of 365), including\n        February 29 as an intercalary day. Leap years are years divisible\n        by 4, except for years divisible by 100 but not by 400.\n\n        See Also\n        --------\n        Timestamp.is_leap_year : Check if the year in a Timestamp is a leap year.\n        DatetimeIndex.is_leap_year : Boolean indicator if the date belongs to a\n            leap year.\n\n        Examples\n        --------\n        >>> period = pd.Period(\0472022-01\047, \047M\047)\n        >>> period.is_leap_year\n        False\n\n        >>> period = pd.Period(\0472020-01\047, \047M\047)\n        >>> period.is_leap_year\n        True\n        "), 0},
  {"freqstr", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period_freqstr, 0, PyDoc_STR("\n        Return a string representation of the frequency.\n\n        This property provides the frequency string associated with the `Period`\n        object. The frequency string describes the granularity of the time span\n        represented by the `Period`. Common frequency strings include \047D\047 for\n        daily, \047M\047 for monthly, \047Y\047 for yearly, etc.\n\n        See Also\n        --------\n        Period.asfreq : Convert Period to desired frequency, at the start or end\n            of the interval.\n        period_range : Return a fixed frequency PeriodIndex.\n\n        Examples\n        --------\n        >>> pd.Period(\0472020-01\047, \047D\047).freqstr\n        \047D\047\n        "), 0},
  {"_ordinal", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period__ordinal, 0, 0, 0},
  {"_dtype", __pyx_getprop_6pandas_5_libs_6tslibs_6period_7_Period__dtype, 0, 0, 0},
  {0, 0, 0, 0, 0}
};
